import sys

def generate_k_lucky_tickets(k, m):
    tickets = set()
    base_ticket = f"{k:08}"
    tickets.add(base_ticket)

    # Generate additional tickets by modifying the base ticket
    for i in range(1, m):
        new_ticket = base_ticket[:-1] + str(int(base_ticket[-1]) + i)
        tickets.add(new_ticket)

    return list(tickets)

def main():
    import sys
    input = sys.stdin.read().strip()
    k, m = map(int, input.split())
    tickets = generate_k_lucky_tickets(k, m)
    for ticket in tickets:
        print(ticket)

if __name__ == "__main__":
    main()
